create table if not exists public.news_submissions (id uuid primary key default gen_random_uuid(),title text not null,details text not null,source_url text,contributor text,status text not null default 'pending' check(status in ('pending','processing','published','cancelled','failed')),telegram_chat_id text,telegram_message_id bigint,article_slug text,created_at timestamptz not null default now(),processed_at timestamptz);
alter table public.articles add column if not exists source_label text;
alter table public.news_submissions enable row level security;
-- No public policies. Only service-role server functions can read/write tips.